from pathlib import Path
import json
from playwright.sync_api import sync_playwright,expect
out=Path(__file__).resolve().parents[2]/'.run/community-polish-2';out.mkdir(parents=True,exist_ok=True)
checks=[];errors=[];fonts=[]
with sync_playwright() as p:
 browser=p.chromium.launch();page=browser.new_page(viewport={'width':1440,'height':1000})
 page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:fonts.append(r.url) if '/fonts/pengzhi-ui-sc.' in r.url else None)
 page.goto('http://127.0.0.1:5173/platform/forum?mode=guest&greenhouse_id=101');page.evaluate('document.fonts.ready')
 assert any('.woff2' in f for f in fonts) and not any(f.endswith('.woff') for f in fonts),fonts;assert page.evaluate('document.fonts.check(\'650 16px "Noto Sans SC"\')');checks.append('Browser loads compressed local font and retains variable weight')
 page.get_by_role('button',name='我的收藏',exact=True).click();expect(page.get_by_text('还没有收藏的讨论',exact=True)).to_be_visible();page.get_by_role('button',name='浏览全部讨论',exact=True).click();expect(page.locator('.forum-post')).to_be_visible();checks.append('Empty favorites guides users back to discussions')
 page.get_by_role('button',name='我的帖子',exact=True).click();expect(page.get_by_text('还没有发布讨论',exact=True)).to_be_visible();page.get_by_role('button',name='发布一篇讨论',exact=True).click();expect(page.get_by_role('dialog',name='发布棚友帖子',exact=True)).to_be_visible();page.locator('.ant-modal-close:visible').click();checks.append('Empty personal posts opens the real editor without publishing')
 page.get_by_role('button',name='浏览全部讨论',exact=True).click();page.locator('.forum-search input').fill('不存在的隔离测试XYZ');page.locator('.forum-search input').press('Enter');expect(page.get_by_text('没有找到符合条件的讨论',exact=True)).to_be_visible();page.get_by_role('button',name='清除筛选条件',exact=True).click();expect(page.locator('.forum-post')).to_be_visible();checks.append('Search empty state clears filters and recovers list')
 # Exercise the actual reader component with explicitly labeled fixture content.
 # No formal document or authenticated API is created by this component test.
 page.evaluate(r'''async()=>{const ReactModule=await import('/node_modules/.vite/deps/react.js');const React=ReactModule.default??ReactModule;const ClientModule=await import('/node_modules/.vite/deps/react-dom_client.js');const {createRoot}=ClientModule.default??ClientModule;const {Modal,ConfigProvider}=await import('/node_modules/.vite/deps/antd.js');const {platformTheme}=await import('/src/theme.ts');const {default:Reader}=await import('/src/pages/Community/KnowledgeDocumentReader.tsx');const host=document.createElement('div');host.id='isolated-reader-check';document.body.appendChild(host);const chunks=Array.from({length:10},(_,i)=>({id:i+1,position:'第'+(i+1)+'页 · 片段1',content:('隔离测试文字，第'+(i+1)+'段。\n').repeat(5)+(i===7?'唯一关键词，番茄观察测试内容。':'普通测试文字。')}));createRoot(host).render(React.createElement(ConfigProvider,{theme:platformTheme},React.createElement(Modal,{open:true,title:'隔离测试文档：引用定位',footer:null,width:800},React.createElement(Reader,{record:{id:-9123,title:'隔离测试文档',chunks,source_url:'https://example.invalid/test-source',applicability:'此处仅验证组件行为，不是农业指导资料。'},chunkId:8}))));}''')
 reader=page.get_by_role('region',name='文档原文阅读',exact=True);expect(reader).to_be_visible();expect(reader.locator('[data-chunk-id="8"]')).to_have_attribute('aria-current','location');page.wait_for_timeout(500);assert reader.locator('.knowledge-reader-chunks').evaluate('e=>e.scrollTop')>0;checks.append('Source chunk is marked and scrolled into view')
 field=page.get_by_label('搜索文档片段',exact=True);field.fill('唯一关键词');expect(reader.locator('.knowledge-reader-chunk')).to_have_count(1);expect(reader.get_by_text('匹配 1 / 10 个片段',exact=True)).to_be_visible();checks.append('Reader searches original chunk content')
 field.fill('第2页 普通');expect(reader.locator('.knowledge-reader-chunk')).to_have_count(1);expect(reader.locator('[data-chunk-id="2"]')).to_be_visible();checks.append('Reader supports page location and multiple search terms')
 field.fill('不存在的片段XYZ');expect(reader.get_by_text('没有匹配的原文片段',exact=True)).to_be_visible();page.get_by_role('button',name='清除片段搜索',exact=True).click();expect(reader.locator('.knowledge-reader-chunk')).to_have_count(10);checks.append('No-result reader search can recover')
 field.fill('第1页');page.get_by_role('button',name='定位引用片段',exact=True).click();expect(field).to_have_value('');expect(reader.locator('[data-chunk-id="8"]')).to_be_focused();checks.append('Citation locator restores original target after filtering')
 page.screenshot(path=str(out/'reader-fixture-desktop.png'))
 page.set_viewport_size({'width':390,'height':844});page.wait_for_timeout(350);assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');expect(field).to_be_visible();page.screenshot(path=str(out/'reader-fixture-mobile.png'));checks.append('Reader is usable without horizontal page overflow on mobile')
 assert not errors,errors;browser.close()
(out/'browser-results.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'errors':errors,'fontRequests':fonts},ensure_ascii=False,indent=2),encoding='utf8');print(len(checks),'community and document reader checks passed')
